// 1. Identifica a origem do evento no Telegram (Mensagem de texto ou Clique de Botão)
const triggerData = $("Telegram Trigger").first().json;
const isCallback = !!triggerData.callback_query;

const chatId = isCallback
  ? triggerData.callback_query.message.chat.id
  : triggerData.message?.chat?.id;

const rawText = isCallback
  ? (triggerData.callback_query.data || '')
  : (triggerData.message?.text || '');

const action = rawText.trim().toLowerCase();

// 2. Extrai todas as cotações retornadas pelo Supabase
let quotes = [];
const supabaseItems = $input.all();
if (supabaseItems && supabaseItems.length > 0) {
  if (Array.isArray(supabaseItems[0].json)) {
    quotes = supabaseItems[0].json;
  } else if (supabaseItems[0].json && Array.isArray(supabaseItems[0].json.data)) {
    quotes = supabaseItems[0].json.data;
  } else {
    quotes = supabaseItems.map(item => item.json);
  }
}

// 3. Funções utilitárias de formatação
const formatMoney = (val) => {
  const num = parseFloat(val) || 0;
  return `R$ ${num.toFixed(2).replace('.', ',')}`;
};

const getBRDate = (isoStr) => {
  if (!isoStr) return '';
  const d = new Date(isoStr);
  return d.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
};

const getBRDateTime = (isoStr) => {
  if (!isoStr) return '';
  const d = new Date(isoStr);
  return d.toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    timeZone: 'America/Sao_Paulo'
  }) + ' às ' + d.toLocaleTimeString('pt-BR', {
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'America/Sao_Paulo'
  });
};

const cleanPhone = (phone) => {
  const digits = (phone || '').replace(/\D/g, '');
  return digits.length === 10 || digits.length === 11 ? '55' + digits : digits;
};

// 4. Cálculos analíticos do painel
const hojeBR = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const cotacoesHoje = quotes.filter(q => getBRDate(q.created_at) === hojeBR);
const cotacoesPendentes = quotes.filter(q => (q.status || 'Novo') === 'Novo');
const cotacoesEmContato = quotes.filter(q => q.status === 'Em Contato');
const cotacoesFechadas = quotes.filter(q => q.status === 'Fechado');

const totalGeral = quotes.length;
const valorTotalGeral = quotes.reduce((acc, q) => acc + (parseFloat(q.valor_total) || 0), 0);
const ticketMedioGeral = totalGeral > 0 ? (valorTotalGeral / totalGeral) : 0;

const valorTotalHoje = cotacoesHoje.reduce((acc, q) => acc + (parseFloat(q.valor_total) || 0), 0);
const ticketMedioHoje = cotacoesHoje.length > 0 ? (valorTotalHoje / cotacoesHoje.length) : 0;

// 5. Montagem da resposta conforme a opção clicada ou digitada
let mensagem = '';

if (action === 'hoje' || action.includes('hoje')) {
  mensagem = `📅 <b>COTAÇÕES DE HOJE (${hojeBR})</b>\n\n` +
    `• Total hoje: <b>${cotacoesHoje.length} cotações</b>\n` +
    `• Volume simulado: <b>${formatMoney(valorTotalHoje)}/mês</b>\n` +
    `• Ticket médio hoje: <b>${formatMoney(ticketMedioHoje)}/mês</b>\n\n`;

  if (cotacoesHoje.length > 0) {
    mensagem += `📋 <b>Leads de hoje:</b>\n`;
    cotacoesHoje.slice(0, 5).forEach((q, idx) => {
      const waLink = `https://wa.me/${cleanPhone(q.whatsapp)}`;
      mensagem += `${idx + 1}. <b>${q.nome || 'Cliente'}</b> - ${formatMoney(q.valor_total)}/mês (${q.status || 'Novo'})\n` +
        `   👉 <a href="${waLink}">Chamar no WhatsApp</a>\n`;
    });
    if (cotacoesHoje.length > 5) {
      mensagem += `\n<i>... e mais ${cotacoesHoje.length - 5} cotações hoje no painel web.</i>\n`;
    }
  } else {
    mensagem += `<i>Nenhuma cotação recebida hoje até o momento.</i>\n`;
  }
} else if (action === 'pendentes' || action.includes('pendente')) {
  mensagem = `⏳ <b>LEADS PENDENTES DE CONTATO</b>\n\n` +
    `Você tem <b>${cotacoesPendentes.length} cotações</b> aguardando primeiro contato:\n\n`;

  if (cotacoesPendentes.length > 0) {
    cotacoesPendentes.slice(0, 5).forEach((q, idx) => {
      const waLink = `https://wa.me/${cleanPhone(q.whatsapp)}`;
      mensagem += `${idx + 1}. <b>${q.nome || 'Cliente'}</b> (${getBRDateTime(q.created_at)})\n` +
        `   💰 ${formatMoney(q.valor_total)}/mês | ${q.fipe_faixa || 'Veículo'}\n` +
        `   👉 <a href="${waLink}">Chamar no WhatsApp</a>\n\n`;
    });
    if (cotacoesPendentes.length > 5) {
      mensagem += `<i>... e mais ${cotacoesPendentes.length - 5} pendentes na fila.</i>\n`;
    }
  } else {
    mensagem += `🎉 <i>Sensacional! Todos os leads recebidos já foram contatados!</i>\n`;
  }
} else if (action === 'ticket' || action.includes('ticket') || action.includes('medio')) {
  const valores = quotes.map(q => parseFloat(q.valor_total) || 0);
  const menor = valores.length > 0 ? Math.min(...valores) : 0;
  const maior = valores.length > 0 ? Math.max(...valores) : 0;
  const somaFechados = cotacoesFechadas.reduce((acc, q) => acc + (parseFloat(q.valor_total) || 0), 0);

  mensagem = `💰 <b>MÉTRICAS FINANCEIRAS - VALORIZA CAR</b>\n\n` +
    `• <b>Ticket Médio Geral:</b> <b>${formatMoney(ticketMedioGeral)}/mês</b>\n` +
    `• <b>Ticket Médio de Hoje:</b> ${formatMoney(ticketMedioHoje)}/mês\n` +
    `• <b>Menor Plano Cotado:</b> ${formatMoney(menor)}/mês\n` +
    `• <b>Maior Plano Cotado:</b> ${formatMoney(maior)}/mês\n` +
    `• <b>Total Simulado (Pipeline):</b> ${formatMoney(valorTotalGeral)}/mês\n` +
    `• <b>Receita Fechada (Recorrente):</b> <b>${formatMoney(somaFechados)}/mês</b>`;
} else if (action === 'ultima' || action.includes('ultima') || action.includes('ultimo')) {
  const q = quotes[0];
  if (q) {
    const waLink = `https://wa.me/${cleanPhone(q.whatsapp)}`;
    const extras = Array.isArray(q.opcionais) && q.opcionais.length > 0 
      ? q.opcionais.map(o => o.title).join(', ') 
      : 'Nenhum opcional selecionado';

    mensagem = `🚀 <b>ÚLTIMA COTAÇÃO RECEBIDA</b>\n\n` +
      `👤 <b>Cliente:</b> ${q.nome || 'Cliente'}\n` +
      `📱 <b>WhatsApp:</b> ${q.whatsapp || '-'}\n` +
      `📄 <b>CPF:</b> ${q.cpf || 'Não informado'}\n` +
      `🚘 <b>Faixa FIPE:</b> ${q.fipe_faixa || '-'}\n` +
      `🚛 <b>Guincho:</b> ${q.reboque || '-'}\n` +
      `✨ <b>Opcionais:</b> ${extras}\n` +
      `💰 <b>Valor Mensal:</b> <b>${formatMoney(q.valor_total)}/mês</b>\n` +
      `📅 <b>Data:</b> ${getBRDateTime(q.created_at)}\n` +
      `📌 <b>Status:</b> ${q.status || 'Novo'}\n\n` +
      `👉 <a href="${waLink}"><b>CLIQUE AQUI PARA FALAR COM O CLIENTE NO WHATSAPP</b></a>`;
  } else {
    mensagem = `<i>Nenhuma cotação registrada no banco de dados.</i>`;
  }
} else if (action === 'total' || action.includes('total')) {
  mensagem = `📈 <b>PANORAMA GERAL DE COTAÇÕES</b>\n\n` +
    `📊 <b>Total Acumulado:</b> <b>${totalGeral} cotações</b>\n` +
    `💰 <b>Pipeline Total Simulado:</b> <b>${formatMoney(valorTotalGeral)}/mês</b>\n` +
    `🎯 <b>Ticket Médio Geral:</b> <b>${formatMoney(ticketMedioGeral)}/mês</b>\n\n` +
    `📌 <b>Distribuição por Status:</b>\n` +
    `• ⏳ Novos / A Contatar: <b>${cotacoesPendentes.length}</b>\n` +
    `• 💬 Em Atendimento: <b>${cotacoesEmContato.length}</b>\n` +
    `• 🤝 Cotações Fechadas: <b>${cotacoesFechadas.length}</b>\n` +
    `• ❌ Canceladas: <b>${quotes.filter(q => q.status === 'Cancelado').length}</b>`;
} else {
  // Menu / Início / Qualquer outra mensagem
  mensagem = `👋 Olá! Sou o <b>Assistente de Gestão da Valoriza Car</b>.\n\n` +
    `Aqui está o resumo instantâneo da sua operação:\n` +
    `• 📅 <b>Cotações hoje:</b> <b>${cotacoesHoje.length}</b> (${formatMoney(valorTotalHoje)}/mês)\n` +
    `• ⏳ <b>Aguardando contato:</b> <b>${cotacoesPendentes.length}</b>\n` +
    `• 📈 <b>Total acumulado:</b> <b>${totalGeral} cotações</b>\n` +
    `• 💰 <b>Ticket médio:</b> ${formatMoney(ticketMedioGeral)}/mês\n\n` +
    `👇 <i>Toque em um dos botões abaixo para consultar:</i>`;
}

return [{
  json: {
    chatId,
    action,
    mensagem
  }
}];
